import { useJsonMemoryView } from "../../src/json-file-transaction.js";
import { extractFixtureScript } from './dashboard-script.js';
import fs from 'node:fs/promises';
import vm from 'node:vm';
import assert from 'node:assert/strict';
import { pathToFileURL } from 'node:url';
import path from 'node:path';
export async function evaluateCustomerResultsCases(inputRoot) {
const root=path.resolve(inputRoot);
const {ownerDailyBrief,revenueLeakRadar,membershipRadar,reviewRadar}=await import(pathToFileURL(root+'/src/growth-intelligence.js'));
const {radarProof}=await import(pathToFileURL(root+'/src/recovery/radarproof.js'));
const {CallHistoryStore}=await import(pathToFileURL(root+'/src/call-history.js'));

const now=new Date('2026-10-02T12:00:00Z'), recent='2026-10-02T10:00:00Z', old='2026-09-01T00:00:00Z';
const rows=[];
function record(id,metric,expected,actual,evidence){let matches=true;try{assert.deepEqual(actual,expected)}catch{matches=false} rows.push({id,metric,status:matches?'supported':'incorrect_or_unavailable',expected,actual,evidence});}
const opp=(id,extra={})=>({id,tenantId:'t1',createdAt:recent,updatedAt:recent,status:'closed',source:'web',...extra});
const store=(opportunities={},attribution={},actions={},events=[])=>({snapshot:async()=>({opportunities,attribution,actions,events})});
const brief=s=>ownerDailyBrief(s,'t1',{now});
let s=store({old:opp('old',{createdAt:old,recovered:true,recoveredAt:recent})});
record('old_lead_new_recovery','Owner Brief recovered · 24h',1,(await brief(s)).recoveredOpportunities,'Persisted opportunity.recoveredAt; opportunity created 31 days earlier');
s=store({legacy:opp('legacy',{recovered:true})});
record('undated_recovery','Owner Brief recovered · 24h',null,(await brief(s)).recoveredOpportunities,'Recovered flag alone has no outcome date');
s=store({future:opp('future',{createdAt:'2026-10-03T00:00:00Z'})},{f:{tenantId:'t1',confirmedAt:'2026-10-03T00:00:00Z',confirmedRevenue:999}});
record('future_owner_data','Owner Brief 24h boundaries',{new:0,revenue:0},{new:(await brief(s)).newOpportunities,revenue:(await brief(s)).confirmedRevenue},'Future creation/confirmation must not appear in completed 24h window');
s=store(); let b=await brief(s),p=await radarProof(s,'t1');
record('empty_counts','Owner Brief opportunity and revenue counts',[0,0,0,0,0,0,0],[b.newOpportunities,b.recoveredOpportunities,b.confirmedRevenue,b.openRevenueLeaks,b.estimatedValueAtRisk,b.membershipRenewalsDue,b.reviewEligibleJobs],'Observed counts from empty supplied snapshot; does not establish source completeness');
record('empty_rates_api','RadarProof no-data rate and latency',[null,null],[p.recoveryRate,p.medianResponseSeconds],'No denominator or timed events');
const html=await fs.readFile(root+'/public/radarproof-dashboard.html','utf8');
const script=extractFixtureScript(html);
const nodes=Object.fromEntries([...html.matchAll(/id="([^"]+)"/g)].map(([,id])=>[id,{value:'',textContent:'',className:'',innerHTML:''}]));
const ctx=vm.createContext({...nodes,document:{getElementById:id=>nodes[id]},sessionStorage:{getItem:()=>'',setItem(){}},location:{search:''},URLSearchParams,Intl,setInterval(){},fetch:async()=>({ok:true,json:async()=>({report:p})})});
vm.runInContext(script.replace('load();\nsetInterval(load,30000);','setInterval(load,30000);'),ctx); await ctx.load();
record('empty_rate_ui','RadarProof recovery rate display','Unavailable',nodes.rate.textContent,'Real inline dashboard script coerces null to zero percent');
s=store({a:opp('a',{recovered:true,estimatedOpportunityValue:5000})},{a:{tenantId:'t1',opportunityId:'a',recovered:true,estimatedOpportunityValue:5000,estimatedRecoveredValue:4000,confirmedRevenue:0}});p=await radarProof(s,'t1');
record('estimated_not_revenue','RadarProof monetary separation',{estimated:5000,recovered:4000,confirmed:0},{estimated:p.estimatedOpportunityValue,recovered:p.estimatedRecoveredValue,confirmed:p.confirmedRevenue},'Attribution fields remain separate; estimate is not collected revenue');
s=store({a:opp('a',{createdAt:old})},{a:{tenantId:'t1',opportunityId:'a',confirmedRevenue:321,confirmedAt:recent,confirmedRevenueSource:'authorized-test-ledger'}});
record('explicit_revenue','Owner Brief confirmed revenue',321,(await brief(s)).confirmedRevenue,'Current attribution amount plus confirmedAt and declared source; no independent payment reconciliation');
s=store({a:opp('a')},{bad:{tenantId:'t2',opportunityId:'a',confirmedRevenue:999,confirmedAt:recent,recovered:true}});p=await radarProof(s,'t1');
record('conflicting_tenant_attribution','Owner Brief and RadarProof tenant isolation',[0,0,0],[(await brief(s)).confirmedRevenue,p.confirmedRevenue,p.recoveredOpportunities],'Other tenant explicitly references local opportunity ID');
s=store({real:opp('real'),other:opp('other',{tenantId:'synthetic-lab',recovered:true})},{other:{tenantId:'synthetic-lab',opportunityId:'other',recovered:true,confirmedRevenue:999}});
p=await radarProof(s,'t1');record('separate_synthetic_tenant','RadarProof captured, recovered, confirmed',[1,0,0],[p.opportunitiesCaptured,p.recoveredOpportunities,p.confirmedRevenue],'Dedicated synthetic tenant excluded by tenant predicate');
s=store({a:opp('a',{metadata:{synthetic:true},recovered:true,recoveredAt:recent,estimatedOpportunityValue:5000})},{a:{tenantId:'t1',opportunityId:'a',recovered:true,estimatedRecoveredValue:5000,confirmedRevenue:123,confirmedAt:recent}});
p=await radarProof(s,'t1');record('same_tenant_synthetic','Owner Brief and RadarProof synthetic record exclusion',[0,0,0,0],[(await brief(s)).newOpportunities,p.opportunitiesCaptured,p.recoveredOpportunities,p.confirmedRevenue],'metadata.synthetic=true retained in opportunity but no reporting exclusion rule exists');
s=store({a:opp('a',{status:'open',type:'phone_lead',estimatedOpportunityValue:500})},{a:{tenantId:'t1',opportunityId:'a',estimatedOpportunityValue:500}},{f:{tenantId:'t1',opportunityId:'a',status:'failed',channel:'human_task'},p:{tenantId:'t1',opportunityId:'a',status:'pending',createdAt:recent,dueAt:recent},b:{tenantId:'t1',opportunityId:'a',status:'blocked',createdAt:recent}});
p=await radarProof(s,'t1');b=await brief(s);const leaks=await revenueLeakRadar(s,'t1',{now});
record('action_metrics','Pending, blocked, leaks and diagnostic risk',[1,1,1,500,1,1,0],[p.pendingActions,p.blockedActions,b.openRevenueLeaks,b.estimatedValueAtRisk,leaks.failedActionCount,leaks.overdueActionCount,p.recoveredOpportunities],'Failed handoff is operational risk, not recovered opportunity; status source is action snapshot');
s=store({m:opp('m',{status:'open',type:'membership_renewal_due',metadata:{renewalDate:'2026-10-10'}}),good:opp('good',{status:'open',type:'job_completed',metadata:{customerSatisfactionKnown:true,customerSatisfied:true}}),bad:opp('bad',{status:'open',type:'job_completed',metadata:{complaintOpen:true}})});
b=await brief(s); record('membership_review_metrics','Owner Brief renewals, review ready and needs check',[1,1,1],[b.membershipRenewalsDue,b.reviewEligibleJobs,b.reviewNeedsHumanCheck],'Open imported opportunity type and job metadata; eligibility is not a review actually received');
s=store({}, {}, {}, [{tenantId:'t1',occurredAt:recent,responseLatencySeconds:5},{tenantId:'t2',occurredAt:recent,responseLatencySeconds:999},{tenantId:'t1',occurredAt:old,responseLatencySeconds:999}]);
p=await radarProof(s,'t1',{sinceMs:Date.parse('2026-10-01T12:00:00Z'),untilMs:now.getTime()});record('latency_scope','RadarProof median response seconds',5,p.medianResponseSeconds,'PR88 existing tenant/window filter retained unchanged');
s=store({}, {}, {}, [{tenantId:'t1',occurredAt:recent,responseLatencySeconds:null},{tenantId:'t1',occurredAt:recent,responseLatencySeconds:-10}]);
p=await radarProof(s,'t1'); record('invalid_latency','RadarProof latency needs valid non-negative numeric evidence',null,p.medianResponseSeconds,'Null coerces to zero and negative duration accepted; neither establishes response latency');
const calls=new CallHistoryStore('/tmp/not-written-results.json');useJsonMemoryView(calls);
calls.data.calls={failed:{callId:'failed',tenantId:'t1',startedAt:now.getTime(),endedAt:now.getTime(),transferred:true,milestones:{'transfer.initiated':{count:1},'transfer.failed':{count:1}},transcript:[{text:'Synthetic fixture turn'}],knowledgeGaps:[{question:'Synthetic fixture gap'}]},other:{callId:'other',tenantId:'t2',transferred:true},spam:{callId:'spam',tenantId:'t1',startedAt:now.getTime(),spamEnded:true}};
const stats=await calls.stats('t1');
record('call_activity_scope','Calls recorded, spam flags, transcript presence, recorded knowledge gaps',[2,1,1,1],[stats.callsHandled,stats.spamScreened,stats.callsWithTranscript,stats.knowledgeGaps],'Tenant-filtered retained call records; no success/voice-quality inference');
const ownerHtml=await fs.readFile(root+'/public/owner-brief.html','utf8');
record('failed_handoff','Failed handoff is honestly labeled as initiation, not completion',{count:1,meaning:'initiated_not_completed',labels:true},{count:stats.humanTransfers,meaning:stats.humanTransfersMeaning??null,labels:html.includes('>Transfers initiated<')&&ownerHtml.includes('>Transfers initiated<')},'Existing transfer flag measures initiation; both dashboards explain it does not establish completed connection');
calls.data.calls.failed.synthetic=true;record('same_tenant_synthetic_call','Synthetic calls excluded from customer call totals',1,(await calls.stats('t1')).callsHandled,'Same-tenant synthetic=true is not excluded');
s=store({a:opp('a',{recovered:true})},{a:{tenantId:'t1',opportunityId:'a',recovered:true},orphan:{tenantId:'t1',opportunityId:'missing',recovered:true}});p=await radarProof(s,'t1');record('orphan_recovery_rate','RadarProof recovery numerator has captured opportunity evidence',1,p.recoveryRate,'Tenant-matching orphan attribution increases numerator without denominator; result exceeds 100%');
s=store({a:opp('a',{source:'web',recovered:true,estimatedOpportunityValue:500})},{a:{tenantId:'t1',opportunityId:'a',recovered:true,estimatedOpportunityValue:500}});p=await radarProof(s,'t1');record('source_breakdown','RadarProof recovery by source',{web:{opportunities:1,recovered:1,estimatedValue:500}},p.bySource,'Opportunity.source, recovered flag and estimatedOpportunityValue; no independent campaign causality');
return {baselineCommit:'21e74ccdddeade9f71aecc29a6b69c5a9703f7a0',testedDirectory:root,at:now.toISOString(),providerCalls:0,records:'local synthetic fixtures only',rows,summary:{supported:rows.filter(x=>x.status==='supported').length,incorrectOrUnavailable:rows.filter(x=>x.status!=='supported').length}};
}
